/* Cookie-consent banner for the cinematic site.
 *
 * The only thing that lets a visitor grant analytics consent. analytics.js
 * (injected on every page by deploy.sh's apply_analytics) loads Google
 * Analytics ONLY after localStorage.ga_cookie === "all"; this banner is what
 * writes that value. Without it a fresh visitor could never consent, so GA
 * never fired — see the cinematic pages shipping analytics.js with no banner.
 *
 * Markup lives in the footer (generated by tools/cinematic/gen.py) and starts
 * with the `hidden` attribute; this script reveals it only when no choice has
 * been stored yet. "Accept all" -> "all" (GA starts, analytics.js polls and
 * picks it up within ~800ms, no reload). "Essential only" -> "essential" (GA
 * stays off). A footer "Cookie settings" link ([data-cc-reopen]) reopens it so
 * the choice can be withdrawn, as the Cookie Policy promises.
 */
(function () {
  "use strict";

  var KEY = "ga_cookie";
  var banner = document.getElementById("cc-banner");
  if (!banner) return;

  function stored() {
    try { return localStorage.getItem(KEY); }
    catch (e) { return null; } // private mode / storage blocked
  }

  function save(value) {
    try { localStorage.setItem(KEY, value); } catch (e) {}
  }

  var lastFocus = null;

  function show() {
    lastFocus = document.activeElement;
    banner.hidden = false;
    // next frame so the entrance transition runs from the hidden state
    requestAnimationFrame(function () { banner.classList.add("is-open"); });
    var first = banner.querySelector(".cc-accent");
    if (first) first.focus();
  }

  function hide() {
    banner.classList.remove("is-open");
    banner.hidden = true;
    if (lastFocus && typeof lastFocus.focus === "function") lastFocus.focus();
  }

  function choose(value) {
    save(value);
    hide();
  }

  banner.addEventListener("click", function (e) {
    var btn = e.target.closest("[data-cc]");
    if (btn) choose(btn.getAttribute("data-cc"));
  });

  // Reopen from the footer link (withdraw / change consent).
  document.addEventListener("click", function (e) {
    var link = e.target.closest("[data-cc-reopen]");
    if (link) { e.preventDefault(); show(); }
  });

  // Show on first visit (no choice stored). An existing choice stays silent;
  // analytics.js reads the same key independently.
  if (stored() == null) {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", show);
    } else {
      show();
    }
  }
})();
